export const DEFAULT_CIRCUIT = CIRCUITS[0].id;

export function circuitById(id: string | null | undefined): Circuit {
	return CIRCUITS.find((c) => c.id === id) ?? CIRCUITS[0];
}

/**
 * The circuit for a race until players choose one (race flow step 2): picked
 * from the race id, so everyone in the same race always sees the same track.
 */
export function circuitForRace(raceId: string): Circuit {
	let h = 7;
	for (const ch of raceId) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
	return CIRCUITS[h % CIRCUITS.length];
}
